import java.util.*;
public class BearCompanyVariant3 {
    static int totalVCount, totalKCount, totalSCount;
    static int[][] frequencyMatrix;
    static ArrayList<Integer>[] positionLists;
    static int[][][][] memoization;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        String str = scanner.next();
        char[] chArr = str.toCharArray();
        totalVCount = totalKCount = totalSCount = 0;
        frequencyMatrix = new int[n + 1][3];
        positionLists = new ArrayList[3];
        for (int i = 0; i < 3; i++) positionLists[i] = new ArrayList<>();
        int idx = 0;
        for (char ch : chArr) {
            System.arraycopy(frequencyMatrix[idx], 0, frequencyMatrix[idx + 1], 0, 3);
            idx++;
            if (ch == 'V') {
                frequencyMatrix[idx][0]++;
                totalVCount++;
                positionLists[0].add(idx);
            } else if (ch == 'K') {
                frequencyMatrix[idx][1]++;
                totalKCount++;
                positionLists[1].add(idx);
            } else {
                frequencyMatrix[idx][2]++;
                totalSCount++;
                positionLists[2].add(idx);
            }
        }
        memoization = new int[totalVCount + 1][totalKCount + 1][totalSCount + 1][3];
        for (int[][][] arr3D : memoization) for (int[][] arr2D : arr3D) for (int[] arr1D : arr2D) Arrays.fill(arr1D, -1);
        System.out.println(solveDP(0, 0, 0, 2));
    }

    static int solveDP(int v, int k, int s, int last) {
        if (v == totalVCount && k == totalKCount && s == totalSCount) return 0;
        if (memoization[v][k][s][last] != -1) return memoization[v][k][s][last];
        int minCost = Integer.MAX_VALUE;
        if (v < totalVCount) {
            int pIdx = positionLists[0].get(v);
            int costVal = Math.max(frequencyMatrix[pIdx][0] - v, 0)
                        + Math.max(frequencyMatrix[pIdx][1] - k, 0)
                        + Math.max(frequencyMatrix[pIdx][2] - s, 0) - 1;
            minCost = Math.min(minCost, solveDP(v + 1, k, s, 0) + costVal);
        }
        if (k < totalKCount && last != 0) {
            int pIdx = positionLists[1].get(k);
            int costVal = Math.max(frequencyMatrix[pIdx][0] - v, 0)
                        + Math.max(frequencyMatrix[pIdx][1] - k, 0)
                        + Math.max(frequencyMatrix[pIdx][2] - s, 0) - 1;
            minCost = Math.min(minCost, solveDP(v, k + 1, s, 1) + costVal);
        }
        if (s < totalSCount) {
            int pIdx = positionLists[2].get(s);
            int costVal = Math.max(frequencyMatrix[pIdx][0] - v, 0)
                        + Math.max(frequencyMatrix[pIdx][1] - k, 0)
                        + Math.max(frequencyMatrix[pIdx][2] - s, 0) - 1;
            minCost = Math.min(minCost, solveDP(v, k, s + 1, 2) + costVal);
        }
        return memoization[v][k][s][last] = minCost;
    }
}
